// Dump returns a map of remote addresses to transport dump results.
// It is panic-safe and returns JSON-serializable data.
func (p *connPool) Dump() interface{} {
	result := make(map[string]interface{})

	defer func() {
		if r := recover(); r != nil {
			klog.Errorf("KITEX: connPool.Dump() panicked: %v", r)
		}
	}()

	p.conns.Range(func(key, value interface{}) bool {
		addr, ok := key.(string)
		if !ok {
			return true
		}

		trans, ok := value.(*transports)
		if !ok {
			return true
		}

		var dumps []interface{}
		for i := 0; i < int(trans.size); i++ {
			tr := trans.cliTransports[i]
			if tr == nil {
				continue
			}

			// Safely extract dump data with type assertion
			if dumper, ok := tr.(interface{ Dump() interface{} }); ok {
				func() {
					defer func() {
						if r := recover(); r != nil {
							klog.Errorf("KITEX: transport.Dump() panicked for address %s: %v", addr, r)
						}
					}()
					dumps = append(dumps, dumper.Dump())
				}()
			}
		}

		if len(dumps) > 0 {
			result[addr] = dumps
		}

		return true
	})

	return result
}

